version.transform:
( 
  $subjectsInput := $$.subjects;
  $subjectKeys := ["productId","processId", "productProcessId", "workcenterId", "lotControlId"];

  $subjectListCombinations := [
    ["productId"],
    ["productId", "processId"],
    ["productId", "workcenterId"],
    ["productId", "processId", "workcenterId"],
    ["processId"],
    ["processId", "workcenterId"],
    ["workcenterId"],
    ["productProcessId"],
    ["productProcessId", "workcenterId"],
    ["lotControlId"]
  ];

  $conditions := ( 
    $map($subjectListCombinations, function($combination) {
      {
        "_and": 
          [
            $map($subjectKeys, function($key) {

                {
                  $key: $key in $combination and $isNotNilOrEmpty($lookup($subjectsInput, $key)) ? 
                    {
                        "_eq": $lookup($subjectsInput, $key)
                    } :
                    {
                        "_isNull": true
                    } 
                }
              } 
            ),
            {
              "usable":{
                "_eq": true
              }
            }
          ]
      }
    }) ~> $uniqBy(function($v){$v._and.**}) ~> $filter(function($v){$not($count($v._and.**._isNull) = 5)})
  );

  {
      "where": {
          "_or": $conditions
      }
  };
)
